# -*- coding: utf-8 -*-
"""受众侧挖掘：从评论区用户出发，读公开收藏夹，聚合出目标群体的偏好共性。

数据源: up_research.json 里每条评论的 commenter_mids（含 night 标记）
抓取: 每个抽样用户 → card(性别/等级) + 公开收藏夹列表 + 每人最多2个夹子的第一页内容
产出: affinity_state.json(断点续跑) / affinity.json / affinity.md

纪律（重要）:
- 只读公开数据；收藏夹为空或不可见的用户直接跳过（尊重隐私设置）
- 只做聚合分析，报告里不出现任何用户名/UID（个人档案不落地、不外发）
- 样本封顶、慢速间隔、412 立即全停
用法: python3 user_affinity.py [--limit 80] [--resume]
"""
import json, time, sys, io, os, re, argparse, random
from collections import Counter

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', line_buffering=True)
os.chdir(os.path.dirname(os.path.abspath(__file__)))

import requests

UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36")
GAP = 2.0
MAX_FOLDERS_PER_USER = 2
MAX_USERS_TOTAL = 120

GENRE_WORDS = ['哄睡', '助眠', '耳音', '采耳', '耳语', '剧情', '管教', '年上', '叔音', '御姐',
               '萝莉', '亲吻', 'kiss', '心跳', '呼吸', '引导', '冥想', '显化', '塔罗', '占卜',
               '催眠', '广播剧', '推文', '小说', '恋爱', '甜宠', '分手', '挽回', '心理', '按摩',
               'asmr', 'ASMR', '音声', ' girlfriend', '男友音', '女友音', '陪睡', '夜用', '专用']


class Abort412(Exception):
    pass


def log(m):
    print(time.strftime('%H:%M:%S ') + str(m))


def get_session():
    s = requests.Session()
    s.headers.update({'User-Agent': UA, 'Accept': 'application/json, text/plain, */*',
                      'Referer': 'https://www.bilibili.com/'})
    try:
        s.get('https://www.bilibili.com/', timeout=15)
        j = s.get('https://api.bilibili.com/x/frontend/finger/spi', timeout=15).json()
        d = j.get('data') or {}
        if d.get('b_3'):
            s.cookies.set('buvid3', d['b_3'], domain='.bilibili.com')
        if d.get('b_4'):
            s.cookies.set('buvid4', d['b_4'], domain='.bilibili.com')
    except Exception as e:
        log(f'cookie init warn: {e}')
    return s


def api(s, url, params=None):
    try:
        r = s.get(url, params=params, timeout=20)
    except Exception as e:
        return {'__code__': 'net', '__msg__': str(e)}
    if r.status_code == 412:
        raise Abort412(url)
    try:
        j = r.json()
    except Exception:
        return {'__code__': 'nonjson', '__msg__': f'http {r.status_code}'}
    if j.get('code') == 0:
        time.sleep(GAP + random.random())
        return j.get('data')
    if j.get('code') == -412:
        raise Abort412(url)
    return {'__code__': j.get('code'), '__msg__': j.get('message')}


def collect_candidates():
    """从 up_research.json 收集评论用户：夜间评论者优先，排除目标 UP 主自己。"""
    data = json.load(open('up_research.json', encoding='utf-8'))
    target_mids = {str(c.get('uid')) for c in data.get('creators', []) if c.get('uid')}
    seen, night_first, others = set(), [], []
    for c in data.get('creators', []):
        for cm in (c.get('comments') or []):
            for u in (cm.get('commenter_mids') or []):
                mid = str(u.get('mid'))
                if not mid or mid in seen or mid in target_mids:
                    continue
                seen.add(mid)
                (night_first if u.get('night') else others).append(mid)
    return night_first + others, len(night_first)


def probe_user(s, mid):
    """card + 公开收藏夹（每人最多 2 个夹子取第一页）。返回用户画像 dict。"""
    d = api(s, 'https://api.bilibili.com/x/web-interface/card', {'mid': mid, 'photo': 'false'})
    if not d or '__code__' in d:
        return {'mid': mid, 'status': f'card_fail:{(d or {}).get("__code__")}'}
    c = d.get('card') or {}
    u = {'mid': mid,
         'sex': c.get('sex') or '保密',
         'level': ((c.get('level_info') or {}).get('current_level')),
         'official': bool((d.get('official') or {}).get('role')),
         'status': 'ok'}
    if u['official']:
        u['status'] = 'official_skip'
        return u
    fl = api(s, 'https://api.bilibili.com/x/v3/fav/folder/created/list-all',
             {'up_mid': mid, 'type': 2})
    folders = []
    if fl and '__code__' not in fl:
        for f in (fl.get('list') or []):
            mc = f.get('media_count') or 0
            if 3 <= mc <= 300:
                folders.append({'id': f.get('id'), 'title': f.get('title'), 'n': mc})
    if not folders:
        u['status'] = 'no_public_fav'
        return u
    u['folders'] = []
    for f in folders[:MAX_FOLDERS_PER_USER]:
        rd = api(s, 'https://api.bilibili.com/x/v3/fav/resource/list',
                 {'media_id': f['id'], 'pn': 1, 'ps': 20, 'order': 'mtime'})
        items = []
        if rd and '__code__' not in rd:
            for m in (rd.get('medias') or []):
                items.append({'title': m.get('title'), 'upper': ((m.get('upper') or {}).get('name'))})
        u['folders'].append({'title': f['title'], 'n': f['n'], 'items': items})
    return u


def aggregate(state):
    users = [u for u in state.values() if u.get('status') == 'ok']
    n = len(users)
    if not n:
        return {'n_users': 0}
    sex = Counter((u.get('sex') or '保密') for u in users)
    levels = sorted(u.get('level') or 0 for u in users)

    def genre_counter(split):
        cnt = Counter()
        for u in users:
            if split and not u.get('night'):
                continue
            if split is False and u.get('night'):
                continue
            texts = [f.get('title') or '' for f in (u.get('folders') or [])]
            for f in (u.get('folders') or []):
                texts += [it.get('title') or '' for it in (f.get('items') or [])]
            blob = ' '.join(texts).lower()
            cnt.update({w: 1 for w in GENRE_WORDS if w.lower() in blob})
        return cnt

    uppers = Counter()
    for u in users:
        names = set()
        for f in (u.get('folders') or []):
            names |= {it.get('upper') for it in (f.get('items') or []) if it.get('upper')}
        uppers.update(names)
    folder_titles = Counter()
    for u in users:
        folder_titles.update({(f.get('title') or '')[:20] for f in (u.get('folders') or [])})
    return {
        'n_users': n,
        'n_night': sum(1 for u in users if u.get('night')),
        'sex_ratio': dict(sex),
        'level_median': levels[len(levels) // 2] if levels else None,
        'genre_all': genre_counter(None).most_common(30),
        'genre_night': genre_counter(True).most_common(15),
        'genre_day': genre_counter(False).most_common(15),
        'top_favorited_uppers': uppers.most_common(20),
        'top_folder_titles': folder_titles.most_common(15),
    }


def write_report(agg):
    if agg.get('n_users', 0) == 0:
        return
    lines = ['# 受众侧挖掘报告（公开收藏夹聚合）', '',
             f'- 样本：{agg["n_users"]} 个有公开收藏夹的用户（其中夜间评论者 {agg["n_night"]}）',
             f'- 性别：{agg["sex_ratio"]}，等级中位数 Lv.{agg["level_median"]}',
             '', '## 品类词覆盖（出现该词的用户数，越多=目标群体越 common）', '']
    for w, c in agg['genre_all']:
        lines.append(f'- {w}: {c}')
    lines += ['', '## 夜间评论者 vs 白天评论者的品类差异', '',
              '夜间: ' + ', '.join(f'{w}({c})' for w, c in agg['genre_night']),
              '白天: ' + ', '.join(f'{w}({c})' for w, c in agg['genre_day']), '',
              '## 被收藏最多的 UP 主（竞品地图）', '']
    for w, c in agg['top_favorited_uppers']:
        lines.append(f'- {w}: {c} 人收藏')
    lines += ['', '## 高频收藏夹标题（需求语言）', '']
    for w, c in agg['top_folder_titles']:
        lines.append(f'- {w} (x{c})')
    with open('affinity.md', 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines))
    log('report -> affinity.md')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--limit', type=int, default=80)
    args = ap.parse_args()
    state = {}
    if os.path.exists('affinity_state.json'):
        state = json.load(open('affinity_state.json', encoding='utf-8'))
    cands, n_night = collect_candidates()
    todo = [m for m in cands if m not in state][:args.limit]
    log(f'候选 {len(cands)} 人（夜间优先 {n_night}），本次处理 {len(todo)}，已完成 {len(state)}')
    s = get_session()
    time.sleep(2)
    aborted = False
    try:
        for i, mid in enumerate(todo, 1):
            u = probe_user(s, mid)
            if u.get('night') is None:
                u['night'] = mid in set(cands[:n_night])
            state[mid] = u
            json.dump(state, open('affinity_state.json', 'w', encoding='utf-8'),
                      ensure_ascii=False)
            log(f'[{i}/{len(todo)}] {mid}: {u.get("status")} folders={len(u.get("folders") or [])}')
            if len(state) >= MAX_USERS_TOTAL:
                log('达到总样本上限，停止')
                break
    except Abort412 as e:
        aborted = True
        log(f'!!! 412 风控，立即全停: {e}（已抓数据已存盘，可 --resume 续跑）')
    agg = aggregate(state)
    json.dump(agg, open('affinity.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    write_report(agg)
    log(f'聚合完成: {agg.get("n_users")} 用户')
    if aborted:
        sys.exit(2)


if __name__ == '__main__':
    main()

