REQ_RE = re.compile(r'(求|能不能|可以不可以|什么时候|下一期|下一集|想听|求出|求更|催更|好想|跪求|可以出|出个|求个)')


def harvest_titles(s):
    out = {}
    for t in TARGETS:
        name, mid = t['name'], str(t['mid'])
        vids = {}
        for page in (1, 2):
            d = api(s, 'https://api.bilibili.com/x/web-interface/wbi/search/type',
                    wbi_sign({'search_type': 'video', 'keyword': name, 'page': page}),
                    headers={'Referer': 'https://search.bilibili.com/'})
            if not d or '__code__' in d:
                log(f'search {name} p{page} failed')
                break
            for r in (d.get('result') or []):
                if str(r.get('mid')) != mid:
                    continue
                bv = r.get('bvid')
                if bv and bv not in vids:
                    vids[bv] = {'bvid': bv, 'aid': r.get('aid'), 'aid': r.get('aid'),
                                'title': re.sub(r'<[^>]+>', '', r.get('title') or ''),
                                'play': r.get('play') or 0,
                                'favorites': r.get('favorites') or 0,
                                'pubdate': r.get('pubdate')}
            if len(vids) >= 40:
                break
        out[name] = list(vids.values())
        log(f'{name}: {len(out[name])} titles')
    return out


def theme_stats(titles_by_creator):
    stat = defaultdict(lambda: {'n': 0, 'total_play': 0, 'max_play': 0, 'samples': []})
    for name, vids in titles_by_creator.items():
        for v in vids:
            title = v['title']
            play = v['play'] or 0
            for theme, words in THEME_WORDS.items():
                hit = next((w for w in words if w.lower() in title.lower()), None)
                if hit:
                    st = stat[theme]
                    st['n'] += 1
                    st['total_play'] += play
                    st['max_play'] = max(st['max_play'], play)
                    if len(st['samples']) < 4:
                        st['samples'].append(f"{title[:26]}({play})")
    return {k: {'n': v['n'], 'total_play': v['total_play'],
                'avg_play': int(v['total_play'] / v['n']) if v['n'] else 0,
                'max_play': v['max_play'], 'samples': v['samples']}
            for k, v in sorted(stat.items(), key=lambda x: -x[1]['total_play'])}


def pick_new_top(titles_by_creator, done_bvids, per=2):
    """每个 UP 主挑播放最高且没挖过评论的 2 条。"""
    picks = []
    for name, vids in titles_by_creator.items():
        top = sorted([v for v in vids if v['bvid'] not in done_bvids and (v['play'] or 0) > 0],
                     key=lambda x: -x['play'])[:per]
        for v in top:
            picks.append((name, v))
    return picks


def mine_requests(reps_list):
    reqs, repeats = [], 0
    for r in reps_list:
        m = ((r.get('content') or {}).get('message') or '').strip()
        if any(w in m for w in REPEAT_WORDS):
            repeats += 1
        if REQ_RE.search(m) and 4 <= len(m) <= 60:
            reqs.append(m[:50])
    return reqs, repeats


def main():
    done_bvids = set()
    try:
        old = json.load(open('up_research.json', encoding='utf-8'))
        for c in old['creators']:
            for cm in c.get('comments') or []:
                done_bvids.add(cm.get('bvid'))
    except Exception:
        pass

    s = get_session()
    time.sleep(2)
    load_wbi(s)
    titles = harvest_titles(s)
    ts = theme_stats(titles)
    log('== 主题词×播放 权重榜 ==')
    for k, v in list(ts.items())[:12]:
        log(f"  {k}: {v['n']}条/总播放{v['total_play']} 均播{v['avg_play']} | {'; '.join(v['samples'][:2])}")

    picks = pick_new_top(titles, done_bvids, per=2)
    comment_data = []
    for name, v in picks:
        log(f"comments {name} {v['bvid']} ({v['title'][:20]}, play={v['play']})")
        reps = replies(s, v['aid'], pages=3, bvid=v['bvid'])
        reqs, repeats = mine_requests(reps)
        comment_data.append({'creator': name, 'bvid': v['bvid'], 'title': v['title'][:30],
                             'play': v['play'], 'n_replies': len(reps), 'n_requests': len(reqs),
                             'requests': reqs[:12]})
        log(f'  -> {len(reps)} 条评论, 求更 {len(reqs)}, 复听词 {repeats}')

    # 弹幕热图：取 3 个最高播放视频
    dm_heat = []
    all_vids = sorted([v for vids in titles.values() for v in vids if (v['play'] or 0) > 1000],
                      key=lambda x: -x['play'])[:3]
    for v in all_vids:
        try:
            r = s.get(f'https://api.bilibili.com/x/v1/dm/list.so?oid={v["aid"]}', timeout=20)
            raw = r.content.decode('utf-8', errors='ignore')
            ps = [float(x) for x in re.findall(r'p="([\d.]+),', raw)]
            if ps:
                buckets = [0] * 10
                for p_ in ps:
                    buckets[min(9, int(p_ / max(ps) * 10))] += 1
                total = sum(buckets)
                heat = ' '.join(f'{i*10}-{(i+1)*10}%:{b}' for i, b in enumerate(buckets) if b)
                dm_heat.append({'bvid': v['bvid'], 'title': v['title'][:26], 'n_dm': total,
                                'heat': heat})
                log(f'danmaku {v["bvid"]}: {total} 条')
                time.sleep(2)
            else:
                log(f'danmaku {v["bvid"]}: 0 条')
                time.sleep(2)
        except Exception as e:
            log(f'danmaku fail {v["bvid"]}: {e}')

    out = {'generated_at': time.strftime('%Y-%m-%d %H:%M'),
           'theme_stats': ts, 'titles': titles,
           'comment_requests': comment_data, 'danmaku_heat': dm_heat}
    json.dump(out, open('harvest.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    log('saved -> harvest.json')


if __name__ == '__main__':
    try:
        main()
    except Abort412 as e:
        log(f'!!! 412 全停: {e}')
        raise SystemExit(2)
